import { autoJsStoreUtils } from '@droid/android';
import { useTranslation } from '@fanfanlo'
import { Box, Button, TextField, Stack } from '@mui/material';
import { useState } from 'react';
import { androidFloatWindowData, generateDefaultWindowName, isTagExists, isValidContent } from './data';

interface AddWindowProps {
  onClose?: () => void;
}

export function AddWindow({ onClose }: AddWindowProps){
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [name, setName] = useState('');
  const [content, setContent] = useState('');
  const [width, setWidth] = useState(0);
  const [height, setHeight] = useState(0);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    // 验证窗口名称
    if (!name.trim()) {
      newErrors.name = t('AddWindow.errorEmptyName');
    } else if (isTagExists(name.trim())) {
      newErrors.name = t('AddWindow.errorDuplicateName');
    }

    // 验证内容
    if (!content.trim()) {
      newErrors.content = t('AddWindow.errorEmptyContent');
    } else if (!isValidContent(content)) {
      newErrors.content = t('AddWindow.errorInvalidContent');
    }

    // 验证宽度
    if (width < 0) {
      newErrors.width = t('AddWindow.errorNegativeWidth');
    }

    // 验证高度
    if (height < 0) {
      newErrors.height = t('AddWindow.errorNegativeHeight');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleAdd = () => {
    if (!validateForm()) {
      return;
    }

    const now = Date.now();
    const finalName = name.trim() || generateDefaultWindowName();
    console.log('adding new window ndroidFloatWindowData.data.windowData.windowList', androidFloatWindowData.data.windowData.windowList)
    androidFloatWindowData.data.windowData.windowList.push({
      tag: finalName,
      contentUrl: content.trim(),
      width: width,
      height: height,
      createdAt: now,
      updatedAt: now,
    });

    // 重置表单
    setName('');
    setContent('');
    setWidth(0);
    setHeight(0);
    setErrors({});

    // 关闭 Dialog（如果提供了 onClose 回调）
    if (onClose) {
      onClose();
    }
  };

  const handleCancel = () => {
    // 重置表单
    setName('');
    setContent('');
    setWidth(0);
    setHeight(0);
    setErrors({});

    // 关闭 Dialog
    if (onClose) {
      onClose();
    }
  };

  return (
    <Box sx={{ p: 2 }}>
      <Stack spacing={2}>
        {/* 窗口名称输入框 */}
        <TextField
          label={t('AddWindow.nameLabel')}
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            if (errors.name) {
              setErrors({ ...errors, name: '' });
            }
          }}
          error={!!errors.name}
          helperText={errors.name || t('AddWindow.nameHelper')}
          placeholder={generateDefaultWindowName()}
          fullWidth
          size="small"
          sx={{ mt: '0.7rem' }}
        />

        {/* URL/HTML 输入框 */}
        <TextField
          label="URL / HTML"
          value={content}
          onChange={(e) => {
            setContent(e.target.value);
            if (errors.content) {
              setErrors({ ...errors, content: '' });
            }
          }}
          error={!!errors.content}
          helperText={errors.content || t('AddWindow.contentHelper')}
          placeholder={t('AddWindow.urlPlaceholder')}
          multiline
          rows={4}
          fullWidth
          size="small"
        />

        {/* 宽度和高度输入框（并排） */}
        <Stack direction="row" spacing={2}>
          <TextField
            label={t('AddWindow.widthLabel')}
            type="number"
            value={width}
            onChange={(e) => {
              const val = Number(e.target.value);
              setWidth(val);
              if (errors.width) {
                setErrors({ ...errors, width: '' });
              }
            }}
            error={!!errors.width}
            helperText={errors.width || t('AddWindow.widthHelper')}
            fullWidth
            size="small"
            inputProps={{ min: 0 }}
          />
          <TextField
            label={t('AddWindow.heightLabel')}
            type="number"
            value={height}
            onChange={(e) => {
              const val = Number(e.target.value);
              setHeight(val);
              if (errors.height) {
                setErrors({ ...errors, height: '' });
              }
            }}
            error={!!errors.height}
            helperText={errors.height || t('AddWindow.heightHelper')}
            fullWidth
            size="small"
            inputProps={{ min: 0 }}
          />
        </Stack>

        {/* 按钮组 */}
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
          <Button
            variant="outlined"
            color="inherit"
            onClick={handleCancel}
          >
            {t('AddWindow.cancelButton')}
          </Button>
          <Button
            variant="contained"
            color="primary"
            onClick={handleAdd}
          >
            {t('AddWindow.addButton')}
          </Button>
        </Box>
      </Stack>
    </Box>
  );
}