import { useTranslation } from '@fanfanlo';
import { Button, Dialog, DialogContent, DialogTitle } from '@mui/material';
import { useState } from 'react';
import { AddWindow } from './AddWindow';
import { useRouter } from 'next/router';

export function AddWindowButton() {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [open, setOpen] = useState(false);
  const router = useRouter();
  const handleOpen = () => {
    router.push('/float-window-add')
    // setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  return (
    <>
      <Button variant="contained" color="primary" onClick={handleOpen}>
        {t('AddWindow.add')}
      </Button>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{t('AddWindow.add')}</DialogTitle>
        <DialogContent sx={{ p: 0 }}>
          <AddWindow onClose={handleClose} />
        </DialogContent>
      </Dialog>
    </>
  );
}
