import { Box } from "@mui/material";
import { AddWindow } from "./AddWindow";
import { WindowList } from "./WindowList";
import { useTranslation } from "react-i18next";
import { useEffect } from "react";
import { androidFloatWindowData } from "./data";
import { useProxyWatch } from "@fanfanlo";
import { AddWindowButton } from "./AddWindowButton";
import { WindowConfList } from "./WindowConfList";


export function WindowPageContent(){
    const {t} = useTranslation('homepage/components/android-float/window/content');
    const [initialized] = useProxyWatch(androidFloatWindowData.data, 'initialized', androidFloatWindowData.data.initialized);
    useEffect(()=>{
        androidFloatWindowData.init();
    }, [])
    return <Box>
        {initialized && <>
        
        <Box sx={{fontSize:20, fontWeight:'bold', mb:2}}>{t('WindowPageContent.title')}</Box>
        <AddWindowButton />
        {/* <WindowList /> */}
        <WindowConfList />
        </>}
    </Box>
}